/**
 * The staged firing flow: match one landed occurrence against a reaction's
 * triggers, filter the matched frames through `where`, then form, ask, and
 * settle each consequence — recording sanitized failures per stage.
 */
import { DESCEND, mapValueTree, mapValueTreeAsync, walkValueTree } from "../../reads/value-tree.js";
import { varKeyOf } from "../../reads/frames.js";
import { Frames } from "../../reads/frames.js";
import { hasMarkerKey, liveOf } from "../../reads/ir.js";
import { fuseFormer, isFusedFormer, } from "../../reads/former-nodes.js";
import { formTree } from "../../reads/former-evaluation.js";
import { logger } from "../../utils/logger.js";
import { serializeError } from "../../utils/redaction.js";
import { normalizePromiseLike } from "../../utils/promise-like.js";
import { uuid } from "../../utils/runtime.js";
import { setOwn } from "../../utils/own-property.js";
import { actionNameOf } from "../concepts/introspect.js";
import { actionId, actionSettlement, byReaction as byAskingReaction, flow, landing, } from "../context.js";
import { ActionConcept, normalizeOutcome } from "./actions.js";
import {} from "./firing.js";
import { errorOutputFromThrown, reactQuietly } from "./instrumenting.js";
import { unifyOutputPattern } from "./matching.js";
import { isDeferred, SettlementBook } from "./settlement.js";
export class FiringPipeline {
    matcher;
    actions;
    firingBook;
    definitions;
    reactionLogger;
    react;
    assertRows;
    consumeAction;
    settlement = new SettlementBook();
    constructor(matcher, actions, firingBook, definitions, reactionLogger, react, assertRows, consumeAction) {
        this.matcher = matcher;
        this.actions = actions;
        this.firingBook = firingBook;
        this.definitions = definitions;
        this.reactionLogger = reactionLogger;
        this.react = react;
        this.assertRows = assertRows;
        this.consumeAction = consumeAction;
    }
    async fire(record, reactions) {
        const prepared = [];
        for (const reaction of reactions) {
            const matched = this.matchTrigger(record, reaction);
            if (matched === undefined)
                continue;
            if (isDeferred(reaction)) {
                this.settlement.arm(record.flow, matched);
                continue;
            }
            const firing = await this.qualify(matched);
            if (firing !== undefined)
                prepared.push(firing);
        }
        for (const firing of prepared)
            await this.dispatch(firing);
    }
    /**
     * Open settlement frontiers for one flow until none qualifies a trigger.
     *
     * Each frontier qualifies every trigger armed in the flow before dispatching
     * any of their consequences, exactly as one landed occurrence does for its
     * siblings, then lets those consequences and the ordinary cascades they
     * start drain before the next frontier opens. An unqualified combination
     * remains armed unless another firing consumes one of its trigger
     * occurrences. An interpreter or integrity failure prevents subsequent
     * frontiers but does not cancel matches already being processed in the current
     * frontier.
     */
    settle(flowToken) {
        if (!this.settlement.has(flowToken) || !this.actions._isFlowOutermost(flowToken))
            return;
        return this.openFrontiers(flowToken);
    }
    async openFrontiers(flowToken) {
        try {
            while (this.settlement.has(flowToken) && !this.actions._flowFailed(flowToken)) {
                const prepared = [];
                for (const armed of this.settlement.pending(flowToken)) {
                    if (!this.retainUnconsumedFrames(armed)) {
                        this.settlement.retire(flowToken, armed);
                        continue;
                    }
                    const firing = await this.qualify(armed);
                    if (firing === undefined)
                        continue;
                    if (!this.retainUnqualifiedFrames(armed, firing.frameTriggerIds)) {
                        this.settlement.retire(flowToken, armed);
                    }
                    prepared.push(firing);
                }
                this.reactionLogger.settlement(flowToken, prepared.length);
                if (prepared.length === 0)
                    return;
                for (const firing of prepared)
                    await this.dispatch(firing);
            }
        }
        finally {
            this.settlement.discard(flowToken);
        }
    }
    /** Match one reaction's `when` against a landed occurrence. */
    matchTrigger(record, reaction) {
        let matched;
        let actionSymbols;
        try {
            [matched, actionSymbols] = this.matcher.match(record, reaction);
            this.assertRows(record.flow, matched.length);
        }
        catch (error) {
            this.failStage(reaction, record.flow, [record.id], "trigger", "trigger matching failed", error);
            return undefined;
        }
        if (matched.length === 0)
            return undefined;
        this.reactionLogger.frames(`Matched \`reaction\`: ${reaction.name} with \`when\`:`, matched);
        return {
            actionSymbols,
            frames: matched,
            provenance: this.capture(matched, record.flow, actionSymbols),
            reaction,
        };
    }
    /** Read one matched trigger's conditions against current state. */
    async qualify(matched) {
        const { actionSymbols, provenance, reaction } = matched;
        let frameTriggerIds = provenance.frameTriggerIds;
        let frames = matched.frames;
        if (reaction.where !== undefined) {
            try {
                const filtered = reaction.where(new Frames(...frames));
                const filteredPromise = normalizePromiseLike(filtered);
                frames = filteredPromise === undefined ? filtered : await filteredPromise;
                if (!(frames instanceof Frames)) {
                    throw new TypeError("A reaction where function must return Frames.");
                }
                this.assertRows(provenance.flow, frames.length);
                frameTriggerIds = this.assertProvenance(frames, provenance, actionSymbols);
            }
            catch (error) {
                this.failStage(reaction, provenance.flow, provenance.triggerIds, "where", "where condition evaluation failed", error);
                return undefined;
            }
            this.reactionLogger.frames("After processing `where`:", frames);
            if (frames.length === 0)
                return undefined;
        }
        return { actionSymbols, frameTriggerIds, frames, provenance, reaction };
    }
    async dispatch(prepared) {
        const { actionSymbols, frameTriggerIds, frames, provenance, reaction } = prepared;
        const active = frames
            .map((_frame, index) => index)
            .filter((index) => !frameTriggerIds[index].some((id) => this.firingBook.hasConsumed(id, reaction.name)));
        if (active.length === 0)
            return;
        try {
            await this.dispatchFrames(new Frames(...active.map((index) => frames[index])), reaction, actionSymbols, provenance, active.map((index) => frameTriggerIds[index]));
        }
        catch (error) {
            this.failStage(reaction, provenance.flow, provenance.triggerIds, "consequence-dispatch", "consequence processing failed", error);
        }
    }
    capture(frames, flowToken, actionSymbols) {
        const frameTriggerIds = frames.map((frame) => this.triggerIdsOf(frame, actionSymbols));
        const triggerIds = [...new Set(frameTriggerIds.flat())];
        return {
            flow: flowToken,
            triggerIds,
            frameTriggerIds,
            ...(actionSymbols.length > 0
                ? { triggerSignatures: new Set(frameTriggerIds.map((ids) => JSON.stringify(ids))) }
                : {}),
        };
    }
    retainFrames(matched, retain) {
        const remaining = matched.provenance.frameTriggerIds
            .map((ids, index) => ({ ids, frame: matched.frames[index] }))
            .filter(({ ids }) => retain(ids));
        if (remaining.length === 0)
            return false;
        if (remaining.length === matched.frames.length)
            return true;
        const frameTriggerIds = remaining.map(({ ids }) => ids);
        matched.frames = new Frames(...remaining.map(({ frame }) => frame));
        matched.provenance = {
            flow: matched.provenance.flow,
            triggerIds: [...new Set(frameTriggerIds.flat())],
            frameTriggerIds,
            ...(matched.actionSymbols.length > 0
                ? { triggerSignatures: new Set(frameTriggerIds.map((ids) => JSON.stringify(ids))) }
                : {}),
        };
        return true;
    }
    /** Drop combinations invalidated when another firing consumed a shared occurrence. */
    retainUnconsumedFrames(matched) {
        return this.retainFrames(matched, (ids) => ids.every((id) => !this.firingBook.hasConsumed(id, matched.reaction.name)));
    }
    /** Keep trigger combinations whose conditions produced no binding at this frontier. */
    retainUnqualifiedFrames(matched, qualifiedIds) {
        const qualified = new Set(qualifiedIds.map((ids) => JSON.stringify(ids)));
        return this.retainFrames(matched, (ids) => !qualified.has(JSON.stringify(ids)));
    }
    assertProvenance(frames, provenance, actionSymbols) {
        const frameTriggerIds = [];
        for (const frame of frames) {
            if (frame[flow] !== provenance.flow) {
                throw new TypeError("A frame transform must preserve the causal flow.");
            }
            const triggerIds = this.triggerIdsOf(frame, actionSymbols);
            if (provenance.triggerSignatures !== undefined &&
                !provenance.triggerSignatures.has(JSON.stringify(triggerIds))) {
                throw new TypeError("A reaction where function must preserve its trigger occurrences.");
            }
            frameTriggerIds.push(triggerIds);
        }
        return frameTriggerIds;
    }
    triggerIdsOf(frame, actionSymbols) {
        return actionSymbols.map((actionSymbol, index) => {
            const id = frame[actionSymbol];
            if (typeof id !== "string") {
                throw new Error(`Matched frame has no action id for trigger ${index + 1}.`);
            }
            return id;
        });
    }
    async dispatchFrames(frames, reaction, actionSymbols, captured, triggerIdsByFrame) {
        for (const [index, frame] of frames.entries()) {
            const fill = {
                reaction: reaction.name,
                flow: captured.flow,
                whenIds: triggerIdsByFrame[index],
                bindings: this.bindingsOf(frame, actionSymbols),
                produced: [],
                marked: false,
            };
            await this.runPipelineForFrame(frame, reaction.then, reaction, fill);
            this.firingBook.record(fill);
        }
    }
    matchThen(then, frame, by, authoritativeFlow) {
        const resolve = (value) => mapValueTree(value, (node) => {
            const key = varKeyOf(node);
            if (key !== undefined) {
                if (!Object.hasOwn(frame, key)) {
                    throw new Error(`Then clause references variable ${String(key)} which is not bound in the current frame.`);
                }
                return frame[key];
            }
            if (isFusedFormer(node)) {
                return fuseFormer(node.former, resolve(node.in));
            }
            if (typeof node === "object" && node !== null) {
                if (hasMarkerKey(node, "$former")) {
                    const payload = node.$former;
                    const ref = liveOf(node) ?? this.definitions.formerNamed(payload.name);
                    if (ref === undefined) {
                        throw new Error(`Then clause references former "${payload.name}", which is not registered.`);
                    }
                    return fuseFormer(ref, resolve(payload.in));
                }
                if (hasMarkerKey(node, "$lit"))
                    return node.$lit;
            }
            return DESCEND;
        });
        const input = {};
        for (const [key, value] of Object.entries(then.input))
            setOwn(input, key, resolve(value));
        input[flow] = authoritativeFlow ?? frame[flow];
        input[actionId] = uuid();
        if (by !== undefined)
            input[byAskingReaction] = by;
        return input;
    }
    bindingsOf(frame, actionSymbols) {
        const reserved = new Set([flow, landing, ...actionSymbols]);
        const bindings = {};
        for (const key of Object.keys(frame))
            setOwn(bindings, key, frame[key]);
        for (const key of Object.getOwnPropertySymbols(frame)) {
            if (!reserved.has(key))
                setOwn(bindings, key.description ?? String(key), frame[key]);
        }
        return bindings;
    }
    async runPipelineForFrame(frame, nodes, reaction, fill) {
        let current = new Frames(frame);
        for (const node of nodes) {
            const next = [];
            for (const currentFrame of current) {
                next.push(...(await this.runStepNode(currentFrame, node, reaction, fill)));
            }
            current = new Frames(...next);
            this.assertRows(fill.flow, current.length);
            if (current.length === 0)
                break;
        }
    }
    async runStepNode(frame, node, reaction, fill) {
        let matched;
        try {
            matched = this.matchThen(node.action, frame, reaction.name, fill.flow);
        }
        catch (error) {
            return this.failStep(reaction, node, fill, "consequence-input", "consequence input could not be formed from the matched bindings", error);
        }
        try {
            matched = await this.resolveFormerInputs(matched);
        }
        catch (error) {
            return this.landFormingFault(matched, node, reaction, fill, error);
        }
        const id = matched[actionId];
        if (typeof id !== "string")
            throw new Error("Action produced from `then` is missing an id.");
        const previouslyMarked = fill.marked;
        this.firingBook.mark(fill);
        let output;
        let settlement;
        matched[actionSettlement] = (next) => {
            settlement = next;
        };
        const runThen = node.action.action;
        try {
            output = (await runThen(matched));
        }
        catch (error) {
            if (settlement !== undefined) {
                fill.produced.push(id);
                logger.error(settlement === "fault-recorded"
                    ? "Consequence action faulted"
                    : "Consequence action failed after its ask was recorded", {
                    action: actionNameOf(node.action.action),
                    actionId: id,
                    error: serializeError(error),
                });
                if (settlement !== "fault-recorded") {
                    this.recordConsequence(node, fill, "consequence-dispatch", error, id);
                }
                return new Frames();
            }
            logger.error("Consequence action failed before its ask was recorded", {
                action: actionNameOf(node.action.action),
                actionId: id,
                error: serializeError(error),
            });
            this.recordConsequence(node, fill, "consequence-dispatch", error, id);
            if (!previouslyMarked)
                this.firingBook.unmark(fill);
            return new Frames();
        }
        fill.produced.push(id);
        const stored = this.actions._getById(id);
        const outcome = (stored === undefined ? undefined : this.actions._matchingRecord(stored).outcome) ??
            normalizeOutcome(output);
        let childFrames;
        try {
            childFrames =
                outcome.kind === "error"
                    ? new Frames({ ...frame })
                    : this.framesWithStepOutput(frame, node.action, outcome);
        }
        catch (error) {
            return this.failStep(reaction, node, fill, "consequence-output", "consequence output matching failed", error, id);
        }
        if (childFrames.length === 0)
            return childFrames;
        if (node.transform !== undefined) {
            try {
                const transformed = node.transform(childFrames);
                const transformedPromise = normalizePromiseLike(transformed);
                childFrames =
                    transformedPromise === undefined ? transformed : await transformedPromise;
                if (!(childFrames instanceof Frames)) {
                    throw new TypeError("An ask result transform must return Frames.");
                }
                this.assertCausalFlow(childFrames, fill.flow);
            }
            catch (error) {
                return this.failStep(reaction, node, fill, "result-transform", "ask result condition failed", error, id);
            }
        }
        return outcome.kind === "error" ? new Frames() : childFrames;
    }
    framesWithStepOutput(frame, pattern, outcome) {
        const extended = unifyOutputPattern(outcome, pattern.output ?? {}, frame);
        return extended === undefined ? new Frames() : new Frames(extended);
    }
    /** Log a stage failure and record its sanitized interpreter evidence. */
    failStage(reaction, flowToken, triggerIds, stage, message, error, consequence = {}) {
        logger.error(`Reaction "${reaction.name}": ${message}`, {
            ...consequence,
            error: serializeError(error),
        });
        this.actions._recordInterpreterFailure(reaction.name, flowToken, triggerIds, stage, error, consequence);
    }
    failStep(reaction, node, fill, stage, message, error, actionIdValue) {
        this.failStage(reaction, fill.flow, fill.whenIds, stage, message, error, {
            action: actionNameOf(node.action.action),
            ...(actionIdValue !== undefined ? { actionId: actionIdValue } : {}),
        });
        return new Frames();
    }
    recordConsequence(node, fill, stage, error, actionIdValue) {
        this.actions._recordInterpreterFailure(fill.reaction, fill.flow, fill.whenIds, stage, error, {
            action: actionNameOf(node.action.action),
            ...(actionIdValue !== undefined ? { actionId: actionIdValue } : {}),
        });
    }
    assertCausalFlow(frames, expected) {
        for (const frame of frames) {
            if (frame[flow] !== expected) {
                throw new TypeError("A frame transform must preserve the causal flow.");
            }
        }
    }
    async landFormingFault(matched, node, reaction, fill, error) {
        const { [flow]: flowToken, [actionId]: id, [byAskingReaction]: askedBy, ...rest } = matched;
        logger.error(`Reaction "${reaction.name}": consequence input former failed`, {
            action: actionNameOf(node.action.action),
            ...(typeof id === "string" ? { actionId: id } : {}),
            error: serializeError(error),
        });
        const concept = node.action.action.concept;
        if (typeof id !== "string" || typeof flowToken !== "string" || concept === undefined) {
            return new Frames();
        }
        if (!this.consumeAction(flowToken))
            return new Frames();
        const describe = (value) => mapValueTree(value, (entry) => isFusedFormer(entry)
            ? { $former: { name: entry.former.formerName, in: entry.in } }
            : DESCEND);
        const record = {
            id,
            action: node.action.action,
            concept,
            input: describe(rest),
            flow: flowToken,
            ...(typeof askedBy === "string" ? { by: askedBy } : {}),
        };
        this.firingBook.mark(fill);
        record.input = this.actions._beginMatchingInput({
            id,
            flow: flowToken,
            input: record.input,
        });
        try {
            this.actions.invoke(record);
            this.actions.faulted({ id, fault: errorOutputFromThrown(error), error });
            fill.produced.push(id);
            await reactQuietly({ react: this.react, emit: () => { } }, { ...record }, 0, "consequence-input fault", { actionId: id });
        }
        finally {
            this.actions._endMatchingInput(flowToken);
        }
        return new Frames();
    }
    async resolveFormerInputs(input) {
        let hasFormer = false;
        for (const value of Object.values(input)) {
            walkValueTree(value, (node) => {
                if (!isFusedFormer(node))
                    return;
                hasFormer = true;
                return false;
            });
            if (hasFormer)
                break;
        }
        if (!hasFormer)
            return input;
        const result = {};
        for (const key of Object.getOwnPropertySymbols(input))
            setOwn(result, key, input[key]);
        for (const [key, value] of Object.entries(input)) {
            setOwn(result, key, await mapValueTreeAsync(value, (node) => isFusedFormer(node)
                ? formTree(node, this.definitions.readEnv(), (count) => this.assertRows(input[flow], count))
                : DESCEND));
        }
        return result;
    }
}
